          playbackId: 'song-test',
          url: 'https://media.example/song.mp3',
          duration: testCase.duration,
          segue: testCase.segue,
          loudness: testCase.loudness,
        }),
      ).rejects.toMatchObject({ reason: 'rejected' });
    }
    expect(fetchImpl).not.toHaveBeenCalled();
