  describe('prepareRecoveryPlaylist validation', () => {
    const invalid: Array<[string, unknown]> = [
      ['a non-array', 'nope'],
      ['an empty list', []],
      ['more than 100 songs', Array.from({ length: 101 }, (_, i) => i + 1)],
      ['duplicates', [1, 1]],
