function idleSnapshot(
  instanceId: string,
  bootId: string,
  sequence: number,
): PalazzoPlaybackState {
  return {
    schemaVersion: 1,
    instanceId,
    bootId,
    sequence,
    availability: 'available',
    status: 'idle',
    liquidsoap: {
      running: true,
      connected: true,
      staleSince: null,
      lastSampleAt: new Date().toISOString(),
    },
    track: null,
    intro: null,
    icecast: { connected: true },
    positionSeconds: 0,
    remainingSeconds: null,
    levels: {
      song: { rms: 0, peak: 0 },
      instant: { rms: 0, peak: 0 },
      output: { rms: 0, peak: 0 },
    },
  };
}

function playingSnapshot(
  instanceId: string,
  bootId: string,
  sequence: number,
  playbackRequestId: string,
  url = 'https://example.test/song-1.mp3',
  title = 'Song one',
  artist = 'Artist one',
): PalazzoPlaybackState {
  return {
    ...idleSnapshot(instanceId, bootId, sequence),
    status: 'playing',
    track: {
      playbackRequestId,
      title,
      artist,
      url,
      startedAt: new Date().toISOString(),
    },
    positionSeconds: 1,
    remainingSeconds: 99,
  };
}

const SEQUENCE = {
  mode: 'autoplay',
  loop: true,
  intervalMs: 500,
  items: [
    {
      id: 'song-1',
      kind: 'preset',
      title: 'Song one',
      artist: 'Artist one',
      coverUrl: 'https://example.test/song-1.jpg',
