      durationMs: 1000,
      songId: 101,
    },
  ],
};

const TWO_SONG_SEQUENCE = {
  ...SEQUENCE,
  items: [
    SEQUENCE.items[0],
    {
      id: 'song-2',
      kind: 'preset',
      title: 'Song two',
      artist: 'Artist two',
      coverUrl: 'https://example.test/song-2.jpg',
