      engine,
      radioService,
      nowPlayingPublisher,
      metrics,
      prisma,
      setPersistedProgramState,
    } = createEngine({ reconciled: true, radio: true });
    const queue = [{ id: 'queue-1', itemId: 'song-2', enqueuedAt: 1 }];
